user = frappe.session.user
roles = set(frappe.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, pluck="role"))
is_admin = user == "Administrator"
is_mgr = is_admin or "Insurance Manager" in roles
is_off = is_admin or "Insurance User" in roles
is_staff = is_mgr or is_off or "System Manager" in roles

employee = frappe.form_dict.get("employee")
member_ok = is_staff
if not member_ok and employee:
    me = frappe.db.get_value("Employee", {"user_id": user}, "name")
    owner = frappe.db.get_value("Insurance Member", employee, "employee")
    member_ok = bool(me and owner and me == owner)
if not member_ok:
    frappe.throw("You are not permitted to view this member.")

name = frappe.form_dict.get("name")
parents = frappe.db.get_all(
    'Insurance Claim',
    filters={
        'employee': employee, 
        'name': ['!=', name],
        'claim_status': ['in', ['Draft', 'Submitted', 'Partially Checked', 'Accepted by Officer',
                                 'Accepted by Manager', 'Sent to Doctor']]
    },
    fields=['name', 'category', 'amount_s']
)

if not parents:
    frappe.response["message"] = []
else:
    category_totals = {}

    for p in parents:
        key = p['category']
        if key  == "Hospitalize":
            category_totals[key] = (category_totals.get(key) or 0) + (p['amount_s'] or 0)

    parent_names = [p['name'] for p in parents]
    result = frappe.db.get_list(
        'Claim Bills',
        filters={
            'parent': ['in', parent_names],
            'parenttype': 'Insurance Claim'
        },
        fields=['category', 'amount'],
        ignore_permissions=True
    )

    for row in result:
        key = row['category']
        if key:
            category_totals[key] = (category_totals.get(key) or 0) + (row['amount'] or 0)

    frappe.response["message"] = [
        {'category': k, 'amount': v}
        for k, v in category_totals.items()
    ]

user = frappe.session.user
roles = set(frappe.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, pluck="role"))
is_admin = user == "Administrator"
is_mgr = is_admin or "Insurance Manager" in roles
is_off = is_admin or "Insurance User" in roles
is_staff = is_mgr or is_off or "System Manager" in roles

employee = frappe.form_dict.get("employee")
member_ok = is_staff
if not member_ok and employee:
    me = frappe.db.get_value("Employee", {"user_id": user}, "name")
    owner = frappe.db.get_value("Insurance Member", employee, "employee")
    member_ok = bool(me and owner and me == owner)
if not member_ok:
    frappe.throw("You are not permitted to view this member.")


parents = frappe.db.get_all(
    'Claim Approval',
    filters={
        'employee': employee,
        'claim_status': ['in', ['Approved', 'Completed']]
    },
    fields=['name', 'claim_no', 'category', 'approved_amount']
)

parents_bal = frappe.db.get_all(
    'Insurance Claim',
    filters={
        'employee': employee,
        'claim_status': ['in', ['Balance BF']]
    },
    fields=['name', 'category', 'amount_s']
)

category_totals = {}

def add_amount(key, value):
    if not key:
        return
    category_totals[key] = frappe.utils.flt(category_totals.get(key)) + frappe.utils.flt(value)

# --- Claim Approval side ---
if parents:
    parent_names = [p['name'] for p in parents]

    approved_bills = frappe.db.get_list(
        'Approved Bill Amounts',
        filters={
            'parent': ['in', parent_names],
            'parenttype': 'Claim Approval'
        },
        fields=['category', 'approved_amount'],
        ignore_permissions=True
    )

    for row in approved_bills:
        add_amount(row['category'], row['approved_amount'])

    # Add parent-level approved_amount only for Hospitalize
    for parent in parents:
        if parent['category'] == "Hospitalize":
            add_amount(parent['category'], parent['approved_amount'])

# --- Insurance Claim (Balance Adjustment) side ---
if parents_bal:
    for p in parents_bal:
        if p['category'] == "Hospitalize":
            add_amount(p['category'], p['amount_s'])

    parent_names_bal = [p['name'] for p in parents_bal]

    claim_bills = frappe.db.get_list(
        'Claim Bills',
        filters={
            'parent': ['in', parent_names_bal],
            'parenttype': 'Insurance Claim'
        },
        fields=['category', 'amount'],
        ignore_permissions=True
    )

    for row in claim_bills:
        add_amount(row['category'], row['amount'])

# --- Final combined output ---
frappe.response["message"] = [
    {'category': k, 'approved_amount': v}
    for k, v in category_totals.items()
]

period = frappe.db.get_value('Insurance Period', 
    {'status': 'Active'}, 
    ['valid_from', 'valid_to'], 
    as_dict=True,
    order_by='modified desc'
)

if period:
    doc.validity = f"{period.valid_from} to {period.valid_to}"
else:
    doc.validity = ''

today = frappe.utils.getdate(frappe.utils.today())

all_periods = frappe.db.get_all("Insurance Period",
    fields=["name", "valid_from", "valid_to", "grace_period_days", "status"])

for period in all_periods:
    valid_from = frappe.utils.getdate(period.valid_from) if period.valid_from else None
    valid_to = frappe.utils.getdate(period.valid_to) if period.valid_to else None
    valid_to_ext = frappe.utils.add_days(valid_to, period.grace_period_days or 0) if valid_to else None

    new_status = period.status
    if valid_from and valid_to:
        if valid_from <= today <= valid_to:
            new_status = "Active"
        elif valid_to_ext and valid_to < today <= valid_to_ext:
            new_status = "Extended"
        else:
            new_status = "Inactive"
    elif valid_from and not valid_to:
        new_status = "Active" if valid_from <= today else "Inactive"

    if new_status != period.status:
        frappe.db.set_value("Insurance Period", period.name, "status", new_status, update_modified=False)

    if new_status == "Extended":
        for member in frappe.get_all("Insurance Member", filters={"member_status": "Active"}, pluck="name"):
            frappe.db.set_value("Insurance Member", member, "validity",
                "Extended until " + str(valid_to_ext), update_modified=False)

today = frappe.utils.getdate(frappe.utils.today())
valid_from = frappe.utils.getdate(doc.valid_from) if doc.valid_from else None
valid_to = frappe.utils.getdate(doc.valid_to) if doc.valid_to else None
valid_to_ext = frappe.utils.add_days(valid_to, doc.grace_period_days)

if valid_from and valid_to:
    if valid_from <= today <= valid_to:
        doc.status = 'Active'
        doc.period = f"{doc.valid_from} to {doc.valid_to}"
    elif valid_to and valid_to_ext:
        if valid_to <= today <= valid_to_ext:
            doc.status = 'Extended'
            doc.period = f"Extended until {valid_to_ext}"
        else:
            doc.status = 'Inactive'
        
elif valid_from and not valid_to:
    if valid_from <= today:
        doc.status = 'Active'
        doc.period = f"{doc.valid_from} to {doc.valid_to}"
    else:
        doc.status = 'Inactive'

user = frappe.session.user
roles = set(frappe.get_all("Has Role", filters={"parent": user, "parenttype": "User"}, pluck="role"))
is_admin = user == "Administrator"
is_mgr = is_admin or "Insurance Manager" in roles
is_off = is_admin or "Insurance User" in roles
is_staff = is_mgr or is_off or "System Manager" in roles

if not (is_off or is_mgr):
    frappe.throw("You are not permitted to do this.")

name = frappe.form_dict.get("name")
claim = frappe.get_doc("Insurance Claim", name)
if claim.docstatus != 1:
    frappe.throw("Claim must be submitted.")
if claim.group_no:
    frappe.throw("Claim is already in a monthly group and cannot be changed.")

update = {}
officer = frappe.form_dict.get("checked_by_officer")
manager = frappe.form_dict.get("checked_by_manager")
status = frappe.form_dict.get("claim_status")
clear = frappe.form_dict.get("clear_assessment")

if officer:
    if officer not in ("Accepted", "Declined"):
        frappe.throw("Invalid officer decision.")
    update["checked_by_officer"] = officer
if manager:
    if not is_mgr:
        frappe.throw("Only an Insurance Manager can set the manager decision.")
    if manager not in ("Accepted", "Declined"):
        frappe.throw("Invalid manager decision.")
    update["checked_by_manager"] = manager
if status:
    allowed = ["Submitted", "Partially Checked", "Accepted by Officer", "Declined by Officer"]
    if is_mgr:
        allowed = allowed + ["Accepted by Manager", "Declined by Manager"]
    if status not in allowed:
        frappe.throw("This status change is not allowed.")
    update["claim_status"] = status
if clear:
    update["checked_by_officer"] = ""
    update["checked_by_manager"] = ""

if update:
    frappe.db.set_value("Insurance Claim", name, update, update_modified=False)
if clear:
    for row in frappe.get_all("Claim Bills", filters={"parent": name}, pluck="name"):
        frappe.db.set_value("Claim Bills", row, {"assessment": "", "remark": ""}, update_modified=False)

frappe.response["message"] = "Success"

for row in doc.get("dependents") or []:
    if not row.marriage_birth_certificate:
        continue

    file_name = frappe.db.get_value("File", {
        "file_url": row.marriage_birth_certificate
    }, "name", order_by="modified desc")

    if file_name:
        frappe.db.set_value("File", file_name, {
            "attached_to_doctype": doc.doctype,
            "attached_to_name"   : doc.name,
        })

#  frappe.call(
#     "document_store.move_dependent_files",
#     doc_name=doc.name
# )

for row in doc.get("details_regarding_bills") or []:
    if not row.attachment:
        continue

    file_name = frappe.db.get_value("File", {
        "file_url": row.attachment
    }, "name", order_by="modified desc")

    if file_name:
        frappe.db.set_value("File", file_name, {
            "attached_to_doctype": doc.doctype,
            "attached_to_name"   : doc.name,
        })

for row in doc.get("claim_files") or []:
    if not row.attachment:
        continue

    file_name = frappe.db.get_value("File", {
        "file_url": row.attachment
    }, "name", order_by="modified desc")

    if file_name:
        frappe.db.set_value("File", file_name, {
            "attached_to_doctype": doc.doctype,
            "attached_to_name"   : doc.name,
        })

old_doc = doc.get_doc_before_save()

if old_doc and old_doc.verify:
    changed = False

    # Fields to ignore in comparison (system/meta fields that always change or aren't meaningful)
    ignore_fields = {
        "modified", "modified_by", "creation", "owner",
        "docstatus", "idx", "_user_tags", "_comments",
        "_assign", "_liked_by", "verify", "approve"
    }

    meta = frappe.get_meta(doc.doctype)

    for df in meta.fields:
        fieldname = df.fieldname
        if fieldname in ignore_fields:
            continue

        if df.fieldtype == "Table":
            # Compare child table rows
            old_rows = old_doc.get(fieldname) or []
            new_rows = doc.get(fieldname) or []

            if len(old_rows) != len(new_rows):
                changed = True
                break

            child_meta = frappe.get_meta(df.options)
            child_ignore = {"modified", "modified_by", "creation", "owner", "docstatus", "idx", "name", "parent", "parentfield", "parenttype"}

            for old_row, new_row in zip(old_rows, new_rows):
                for cdf in child_meta.fields:
                    cfieldname = cdf.fieldname
                    if cfieldname in child_ignore:
                        continue
                    if old_row.get(cfieldname) != new_row.get(cfieldname):
                        changed = True
                        break
                if changed:
                    break
            if changed:
                break

        else:
            # Compare regular fields
            if old_doc.get(fieldname) != doc.get(fieldname):
                changed = True
                break

    if changed:
        doc.verify = 0
        frappe.msgprint(
            "This document was modified after verification. Verification has been reset.",
            alert=True,
            indicator="orange"
        )

doc.claim_status = "Rejected"

if doc.purchase_order:
    pis = frappe.get_all("Purchase Invoice",
        filters={"bill_no": doc.purchase_order, "docstatus": 1}, pluck="name")
    for pi_name in pis:
        frappe.get_doc("Purchase Invoice", pi_name).cancel()

    po = frappe.get_doc("Purchase Order", doc.purchase_order)
    if po.docstatus == 1:
        po.cancel()

claims = [r.claim for r in (doc.claim_nos or []) if r.claim]
if doc.claim_no:
    claims.append(doc.claim_no)
for c in set(claims):
    frappe.db.set_value("Insurance Claim", c, "claim_status", "Accepted by Manager", update_modified=False)

if doc.claim_group:
    frappe.db.set_value("Employee Claim Group", doc.claim_group, "group_status", "Active", update_modified=False)

# When the Claim Approval workflow is active, the workflow owns claim_status and
# the check boxes simply follow it. Otherwise the original role-based logic runs.
if frappe.db.exists("Workflow", {"document_type": "Claim Approval", "is_active": 1}):
    if doc.docstatus == 0:
        doc.checked_by_officer = 1 if doc.claim_status in ("Checked by Officer", "Checked by Manager") else 0
        doc.checked_by_manager = 1 if doc.claim_status == "Checked by Manager" else 0
else:
    if frappe.session.user in ("Administrator", "Guest") or frappe.flags.in_test:
        pass
    else:
        user_doc = frappe.get_doc("User", frappe.session.user)
        user_roles = {r.role for r in user_doc.roles}

        manager_roles = {"Insurance Manager"}
        officer_roles = {"Insurance User"}

        if manager_roles & user_roles:
            if doc.checked_by_manager:
                doc.claim_status = "Checked by Manager"
            elif not doc.checked_by_manager and doc.checked_by_officer:
                doc.claim_status = "Checked by Officer"
        elif officer_roles & user_roles:
            if doc.checked_by_officer and not doc.checked_by_manager:
                doc.claim_status = "Checked by Officer"
            elif not doc.checked_by_officer and not doc.checked_by_manager:
                doc.claim_status = "To Confirm"
            elif doc.checked_by_manager:
                frappe.throw("Cannot change document!")

if doc.verify == 1:
    roles = frappe.get_all(
        'Has Role',
        filters={'parenttype': 'User', 'parent': frappe.session.user},
        pluck='role'
    )
    
    if 'HR User' not in roles and 'HR Manager' not in roles:
        frappe.throw(_("Cannot edit after verification process!"))

# Keeps the officer / manager decision fields, accepted amount and bill assessments in step with the
# Insurance Claim Workflow state, and checks the bill assessments before an officer decision.
old = doc.get_doc_before_save()
old_state = old.claim_status if old else None
st = doc.claim_status
changed = old_state != st

rows = doc.details_regarding_bills or []
assessed = [r for r in rows if r.assessment]
declined = [r for r in rows if r.assessment == "Declined"]

if changed and st == "Accepted by Officer":
    if len(assessed) != len(rows) or len(declined) > 0:
        frappe.throw("Every bill must be assessed and none may be Declined before the claim can be accepted.")
if changed and st == "Declined by Officer":
    if len(assessed) != len(rows) or len(declined) == 0:
        frappe.throw("Assess every bill and decline at least one before declining the claim.")
if changed and st == "Partially Checked":
    if len(assessed) == 0:
        frappe.throw("Assess at least one bill first.")

if st in ("Accepted by Officer", "Accepted by Manager", "Declined by Manager"):
    doc.checked_by_officer = "Accepted"
elif st == "Declined by Officer":
    doc.checked_by_officer = "Declined"
elif st in ("Submitted", "Partially Checked"):
    doc.checked_by_officer = ""

if st == "Accepted by Manager":
    doc.checked_by_manager = "Accepted"
elif st == "Declined by Manager":
    doc.checked_by_manager = "Declined"
elif st in ("Submitted", "Partially Checked", "Accepted by Officer", "Declined by Officer"):
    doc.checked_by_manager = ""

if changed and st == "Submitted" and old_state not in (None, "Draft"):
    # revoked back to the start: clear the officer's assessments
    for r in rows:
        r.assessment = ""
        r.remark = ""

if st in ("Submitted", "Partially Checked", "Accepted by Officer", "Declined by Officer", "Accepted by Manager", "Declined by Manager"):
    total = 0
    for r in rows:
        if r.assessment == "Accepted":
            total = total + frappe.utils.flt(r.amount)
    doc.accepted_amount = total
